-- Workspace.category (SLA-885): general | faceless. The "no real people,
-- celebrities or public figures" lock belongs to the faceless category, not to
-- every workspace. Existing rows become 'general'.
--
-- Mirrors the field in prisma/schema.prisma (and prisma/schema.sqlite.prisma,
-- generated by src/scripts/sync-sqlite-schema.ts).
--
-- Apply with: wrangler d1 migrations apply slashloop --remote
-- Then set the faceless workspace (name-match is deliberately not in the
-- migration; one-off, run by the operator):
--   UPDATE "Workspace" SET "category" = 'faceless' WHERE "id" = '<faceless maxxing workspace id>';
ALTER TABLE "Workspace" ADD COLUMN "category" TEXT NOT NULL DEFAULT 'general';
